package questie

import "testing"

func TestTraces(t *testing.T) {
	raw := `local QuestieDB = QuestieLoader:ImportModule("QuestieDB")
-- Generated by QuestieTrace extract
function ForeverItemTraces:Load()
    local itemKeys = QuestieDB.itemKeys

    return {
        [276070] = {
            [itemKeys.name] = "Chol'aruk's Head", -- a head
            [itemKeys.npcDrops_add] = {267307},
        },
        [277196] = {
            [itemKeys.name] = "Field Accounts",
            [itemKeys.objectDrops_add] = {660731},
        },
        [474] = {
            [questKeys.startedBy_add] = {nil,{630696}},
        },
    }
end
`
	tr, err := traces(raw)
	if err != nil {
		t.Fatal(err)
	}
	if it, ok := tr[276070].(Table); !ok || it["name"] != "Chol'aruk's Head" {
		t.Fatalf("item: %#v", tr[276070])
	}
	if q, ok := tr[474].(Table); !ok || len(list(q["startedBy_add"])) != 2 {
		t.Fatalf("quest: %#v", tr[474])
	}
}
